import calendar, glob, hashlib, json, math, os, re, time
s = os.path.realpath(os.path.expanduser('~/rm/relentless/store'))
ok_ends = ('finish', 'done', 'unhold', 'blocked')
slug = re.compile(r'^[a-z][a-z0-9_]{0,39}$')
idr = re.compile(r'^[A-Za-z0-9_]{1,120}$')
w = lambda v: v if isinstance(v, str) and slug.match(v) else 'other'
num = lambda v: v if isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v) else 0
def e(t):
    try:
        return calendar.timegm(time.strptime(str(t)[:19], '%Y-%m-%dT%H:%M:%S'))
    except (ValueError, TypeError):
        return None
def j(p):
    try:
        with open(p, encoding='utf-8') as f:
            return json.load(f)
    except (OSError, ValueError):
        return None
now = time.time()
print('store %s read_at=%s' % (s, time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime(now))))
try:
    names = sorted(os.listdir(os.path.join(s, 'items')))
except OSError as x:
    print('NO_STORE', str(x)[:120])
    raise SystemExit(0)
byh, started, failed, rows, stat = {}, {}, {}, [], {}
names = [n for n in names if idr.match(n)]
for n in names:
    byh[hashlib.sha1(n.encode()).hexdigest()[:10]] = n
    st = j(os.path.join(s, 'items', n, 'state.json'))
    st = st if isinstance(st, dict) else {}
    ends = {}
    try:
        with open(os.path.join(s, 'items', n, 'attempts.jsonl'), encoding='utf-8') as f:
            for ln in f:
                try:
                    r = json.loads(ln)
                except ValueError:
                    continue
                if not isinstance(r, dict) or not isinstance(r.get('gen'), int):
                    continue
                if r.get('start'):
                    started[(n, r['gen'])] = e(r.get('at'))
                elif r.get('end') and 'kind' not in r:
                    k = w(r['end'])
                    ends[k] = ends.get(k, 0) + 1
                    if k not in ok_ends:
                        failed[(n, r['gen'])] = k
    except OSError:
        pass
    sts = w(st.get('status'))
    stat[sts] = stat.get(sts, 0) + 1
    rows.append((-num(st.get('spent')), n, sts, st.get('gen') if isinstance(st.get('gen'), int) else '-', num(st.get('returns')), num(st.get('spent')), ends))
print('items %d by_status %s' % (len(names), ' '.join('%s=%d' % kv for kv in sorted(stat.items()))))
day = {}
for p in sorted(glob.glob(os.path.join(s, 'spend-*.json'))):
    sp = j(p)
    runs = sp.get('runs') if isinstance(sp, dict) else None
    if not isinstance(runs, dict):
        print('spend %s UNREADABLE' % re.sub(r'[^\w.-]', '_', os.path.basename(p))[:40])
        continue
    d = os.path.basename(p)[6:14]
    if not d.isdigit():
        continue
    day[d] = runs
    print('spend %s spent=%d runs=%d' % (d, num(sp.get('spent')), len(runs)))
rx = re.compile(r'rm-relentless-(work|check)-([0-9a-f]{10})-g(\d+)')
for hours in (24, 72):
    lo = now - hours * 3600.0
    d0 = time.strftime('%Y%m%d', time.gmtime(lo))
    tot = ret = unm = 0
    be = {}
    for d, runs in sorted(day.items()):
        if d < d0:
            continue
        for m, tk in runs.items():
            tk = num(tk)
            if not tk:
                continue
            g = rx.match(m)
            key = (byh.get(g.group(2)), int(g.group(3))) if g else None
            t = started.get(key) if key else None
            if t is None:
                unm += tk
                continue
            if not lo <= t <= now + 300:
                continue
            tot += tk
            if key in failed:
                ret += tk
                k = '%s/%s' % (failed[key], g.group(1))
                be[k] = be.get(k, 0) + tk
    print('returned window_h=%d total=%d returned=%d pct=%.1f unmapped=%d' % (hours, tot, ret, 100.0 * ret / tot if tot else 0, unm))
    for k, v in sorted(be.items(), key=lambda kv: (-kv[1], kv[0]))[:12]:
        print('  by_end %s tokens=%d pct=%.1f' % (k, v, 100.0 * v / tot if tot else 0))
rows.sort()
out, more = 0, 0
for _, n, sts, gen, rets, sp, ends in rows:
    ln = 'item %s h=%s status=%s gen=%s returns=%s spent=%s ends=%s' % (n, hashlib.sha1(n.encode()).hexdigest()[:10], sts, gen, rets, sp, ','.join('%s:%d' % kv for kv in sorted(ends.items())) or '-')
    if out + len(ln) > 14000:
        more += 1
        continue
    out += len(ln) + 1
    print(ln)
if more:
    print('... %d more items (smaller spent)' % more)

import os
roots = tuple(os.path.realpath(os.path.expanduser(x)) for x in ('~/rm', '/tmp'))
for p in sorted((x for x in os.listdir('/proc') if x.isdigit()), key=int):
    try:
        c = os.readlink('/proc/%s/cwd' % p)
        a = open('/proc/%s/cmdline' % p, 'rb').read().split(b'\0')[:2]
    except OSError:
        continue
    if c.startswith(roots):
        print(p, c, ' '.join(os.path.basename(x.decode('utf-8', 'replace')) for x in a))
